import { useCallback, useEffect, useState } from 'react';
import { ActivityIndicator, Pressable, StyleSheet, Text, View } from 'react-native';

import {
  IDLE_MAP_BOOTSTRAP_STATE,
  type MapBootstrapState,
  runMapBootstrap,
} from './bootstrap/mapBootstrapState';
import { MapViewport } from './map/MapViewport';
import {
  createInitialMapTransform,
  mapTransformsEqual,
  type MapTransform,
} from './map/mapTransform';

function nextAttemptFromState(state: MapBootstrapState): number {
  if (state.phase === 'idle') {
    return 1;
  }

  return state.attempt + 1;
}

function phaseMessage(state: MapBootstrapState): string {
  switch (state.phase) {
    case 'idle':
      return 'Preparing startup checks.';
    case 'loading':
      return `Loading ${state.currentPhase} contract from ${state.endpoint}.`;
    case 'ready':
      return 'CampusNav map is ready for visitor navigation.';
    case 'error':
      return state.message;
  }
}

function formatMetric(value: number): string {
  if (!Number.isFinite(value)) {
    return '0';
  }

  return value.toFixed(2);
}

export default function App() {
  const [bootstrapState, setBootstrapState] = useState<MapBootstrapState>(IDLE_MAP_BOOTSTRAP_STATE);
  const [transformState, setTransformState] = useState<MapTransform>(createInitialMapTransform());

  const executeBootstrap = useCallback(async (attempt: number) => {
    const result = await runMapBootstrap({ attempt });

    for (const transition of result.transitions) {
      if (transition.phase === 'loading') {
        console.info('[mobile-bootstrap]', {
          phase: transition.phase,
          attempt: transition.attempt,
          currentPhase: transition.currentPhase,
          endpoint: transition.endpoint,
        });
      }

      if (transition.phase === 'ready') {
        console.info('[mobile-bootstrap]', {
          phase: transition.phase,
          attempt: transition.attempt,
          endpoint: transition.image.endpoint,
        });
      }

      if (transition.phase === 'error') {
        console.warn('[mobile-bootstrap]', {
          phase: transition.phase,
          attempt: transition.attempt,
          failedPhase: transition.failedPhase,
          endpoint: transition.endpoint,
          reason: transition.reason,
          recoverable: transition.recoverable,
        });
      }
    }

    setBootstrapState(result.state);
  }, []);

  useEffect(() => {
    void executeBootstrap(1);
  }, [executeBootstrap]);

  const onRetryPress = () => {
    void executeBootstrap(nextAttemptFromState(bootstrapState));
  };

  const onTransformChange = useCallback((nextTransform: MapTransform) => {
    setTransformState((current) =>
      mapTransformsEqual(current, nextTransform)
        ? current
        : {
            scale: nextTransform.scale,
            rotationDeg: nextTransform.rotationDeg,
            translation: { ...nextTransform.translation },
          },
    );
  }, []);

  return (
    <View style={styles.container}>
      <Text style={styles.title}>CampusNav</Text>
      <Text style={styles.subtitle}>Visitor runtime shell (no sign-in)</Text>

      <Text style={styles.statusLabel}>Bootstrap phase: {bootstrapState.phase}</Text>
      <Text style={styles.statusMessage}>{phaseMessage(bootstrapState)}</Text>

      {bootstrapState.phase === 'loading' ? (
        <View style={styles.loadingRow}>
          <ActivityIndicator size="small" color="#38bdf8" />
          <Text style={styles.loadingText}>{bootstrapState.currentPhase}</Text>
        </View>
      ) : null}

      {bootstrapState.phase === 'ready' ? (
        <View style={styles.readyContainer}>
          <Text style={styles.readyText}>API endpoint: {bootstrapState.apiBaseUrl}</Text>
          <Text style={styles.readyText}>Image endpoint: {bootstrapState.image.endpoint}</Text>
          <Text style={styles.readyText}>
            Graph buildings: {bootstrapState.graph.graph.buildings.length}
          </Text>
          <MapViewport imageUri={bootstrapState.image.endpoint} onTransformChange={onTransformChange} />
          <Text style={styles.telemetryText}>
            viewport scale={formatMetric(transformState.scale)} rotation={formatMetric(transformState.rotationDeg)}°
            tx={formatMetric(transformState.translation.x)} ty={formatMetric(transformState.translation.y)}
          </Text>
        </View>
      ) : null}

      {bootstrapState.phase === 'error' ? (
        <View style={styles.errorContainer}>
          <Text style={styles.errorReason}>Failed phase: {bootstrapState.failedPhase}</Text>
          <Text style={styles.errorReason}>Reason: {bootstrapState.reason}</Text>
          <Text style={styles.errorReason}>Endpoint: {bootstrapState.endpoint ?? 'n/a'}</Text>
          <Pressable onPress={onRetryPress} style={styles.retryButton}>
            <Text style={styles.retryButtonText}>Retry startup</Text>
          </Pressable>
        </View>
      ) : null}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#020617',
    paddingHorizontal: 20,
    paddingVertical: 16,
    gap: 8,
  },
  title: {
    color: '#f8fafc',
    fontSize: 28,
    fontWeight: '700',
  },
  subtitle: {
    color: '#cbd5e1',
    fontSize: 14,
    marginBottom: 4,
  },
  statusLabel: {
    color: '#e2e8f0',
    fontSize: 15,
    fontWeight: '600',
  },
  statusMessage: {
    color: '#94a3b8',
    fontSize: 13,
    marginBottom: 4,
  },
  loadingRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 8,
  },
  loadingText: {
    color: '#38bdf8',
    fontSize: 13,
  },
  readyContainer: {
    flex: 1,
    gap: 8,
  },
  readyText: {
    color: '#38bdf8',
    fontSize: 12,
  },
  telemetryText: {
    color: '#64748b',
    fontSize: 12,
    fontVariant: ['tabular-nums'],
  },
  errorContainer: {
    marginTop: 6,
    gap: 4,
  },
  errorReason: {
    color: '#fda4af',
    fontSize: 12,
  },
  retryButton: {
    marginTop: 6,
    backgroundColor: '#0f172a',
    borderColor: '#475569',
    borderWidth: 1,
    borderRadius: 8,
    paddingHorizontal: 14,
    paddingVertical: 8,
    alignSelf: 'flex-start',
  },
  retryButtonText: {
    color: '#f8fafc',
    fontSize: 13,
    fontWeight: '600',
  },
});

import type { NavFloor } from '../../src/shared/types';
import type { NormalizedNavGraph } from '../domain/navGraph';
import { normalizeNavGraph } from '../domain/navGraph';
import {
  type FloorPlanTarget,
  type MapApiClient,
  type MapApiErrorReason,
  type MapApiResult,
  type MapImageContract,
  createMapApiClient,
} from '../data/mapApiClient';
import { validateApiBaseUrl } from './appBootstrap';

export type MapBootstrapFetchPhase = 'map' | 'image';

export type MapBootstrapErrorReason =
  | 'missing-api-base-url'
  | 'invalid-api-base-url'
  | MapApiErrorReason
  | 'normalization-failure'
  | 'empty-graph';

export type MapBootstrapState =
  | {
      phase: 'idle';
      authRequired: false;
    }
  | {
      phase: 'loading';
      authRequired: false;
      attempt: number;
      startedAtMs: number;
      currentPhase: MapBootstrapFetchPhase;
      endpoint: string;
    }
  | {
      phase: 'ready';
      authRequired: false;
      attempt: number;
      apiBaseUrl: string;
      graph: NormalizedNavGraph;
      image: MapImageContract;
      imageTarget: FloorPlanTarget;
    }
  | {
      phase: 'error';
      authRequired: false;
      attempt: number;
      reason: MapBootstrapErrorReason;
      message: string;
      failedPhase: 'config' | MapBootstrapFetchPhase;
      endpoint: string | null;
      recoverable: boolean;
      details?: string[];
    };

export interface MapBootstrapResult {
  state: MapBootstrapState;
  transitions: MapBootstrapState[];
}

export interface MapBootstrapOptions {
  env?: Record<string, string | undefined>;
  attempt?: number;
  now?: () => number;
  clientFactory?: (baseUrl: string) => MapApiClient;
}

const IDLE_STATE: MapBootstrapState = {
  phase: 'idle',
  authRequired: false,
};

export const IDLE_MAP_BOOTSTRAP_STATE = IDLE_STATE;

function loadingState(
  currentPhase: MapBootstrapFetchPhase,
  endpoint: string,
  attempt: number,
  now: () => number,
): MapBootstrapState {
  return {
    phase: 'loading',
    authRequired: false,
    attempt,
    startedAtMs: now(),
    currentPhase,
    endpoint,
  };
}

function toConfigError(reason: 'missing-api-base-url' | 'invalid-api-base-url', message: string, attempt: number): MapBootstrapState {
  return {
    phase: 'error',
    authRequired: false,
    attempt,
    reason,
    message,
    failedPhase: 'config',
    endpoint: null,
    recoverable: false,
  };
}

function toMapApiError(
  failedPhase: MapBootstrapFetchPhase,
  attempt: number,
  result: Extract<MapApiResult<unknown>, { ok: false }>,
): MapBootstrapState {
  const isRecoverable = result.error.reason !== 'contract-validation-error';

  return {
    phase: 'error',
    authRequired: false,
    attempt,
    reason: result.error.reason,
    message: result.error.message,
    failedPhase,
    endpoint: result.error.endpoint,
    recoverable: isRecoverable,
    ...(result.error.details ? { details: result.error.details } : {}),
  };
}

function toNormalizationError(
  attempt: number,
  endpoint: string,
  message: string,
  details?: string[],
): MapBootstrapState {
  return {
    phase: 'error',
    authRequired: false,
    attempt,
    reason: 'normalization-failure',
    message,
    failedPhase: 'map',
    endpoint,
    recoverable: false,
    ...(details && details.length > 0 ? { details } : {}),
  };
}

function toEmptyGraphError(attempt: number, endpoint: string): MapBootstrapState {
  return {
    phase: 'error',
    authRequired: false,
    attempt,
    reason: 'empty-graph',
    message: 'Map payload contained no floors to bootstrap.',
    failedPhase: 'map',
    endpoint,
    recoverable: false,
  };
}

function pickInitialFloor(graph: NormalizedNavGraph): FloorPlanTarget | null {
  for (const building of graph.graph.buildings) {
    const floor = pickFirstFloor(building.floors);
    if (!floor) {
      continue;
    }

    return {
      buildingId: building.id,
      floorNumber: floor.floorNumber,
    };
  }

  return null;
}

function pickFirstFloor(floors: NavFloor[]): NavFloor | null {
  if (floors.length === 0) {
    return null;
  }

  const sortedFloors = [...floors].sort((a, b) => a.floorNumber - b.floorNumber);
  return sortedFloors[0] ?? null;
}

export async function runMapBootstrap(options: MapBootstrapOptions = {}): Promise<MapBootstrapResult> {
  const attempt = Math.max(1, options.attempt ?? 1);
  const env = options.env ?? process.env;
  const now = options.now ?? Date.now;

  const apiBase = validateApiBaseUrl(env.EXPO_PUBLIC_API_BASE_URL);
  if (!apiBase.ok) {
    const configError = toConfigError(apiBase.reason, apiBase.message, attempt);
    return {
      state: configError,
      transitions: [configError],
    };
  }

  const client = options.clientFactory
    ? options.clientFactory(apiBase.normalizedUrl)
    : createMapApiClient({ baseUrl: apiBase.normalizedUrl });

  const transitions: MapBootstrapState[] = [];

  const mapLoading = loadingState('map', client.resolveMapUrl(), attempt, now);
  transitions.push(mapLoading);

  const mapResult = await client.fetchMapGraph();
  if (!mapResult.ok) {
    const mapError = toMapApiError('map', attempt, mapResult);
    transitions.push(mapError);
    return {
      state: mapError,
      transitions,
    };
  }

  const normalized = normalizeNavGraph(mapResult.data);
  if (!normalized.ok) {
    const normalizationError = toNormalizationError(
      attempt,
      mapResult.endpoint,
      normalized.error.message,
      [normalized.error.code],
    );
    transitions.push(normalizationError);
    return {
      state: normalizationError,
      transitions,
    };
  }

  const imageTarget = pickInitialFloor(normalized.data);
  if (!imageTarget) {
    const emptyGraphError = toEmptyGraphError(attempt, mapResult.endpoint);
    transitions.push(emptyGraphError);
    return {
      state: emptyGraphError,
      transitions,
    };
  }

  const imageLoading = loadingState(
    'image',
    client.resolveFloorPlanImageUrl(imageTarget),
    attempt,
    now,
  );
  transitions.push(imageLoading);

  const imageResult = await client.fetchFloorPlanImageContract(imageTarget);
  if (!imageResult.ok) {
    const imageError = toMapApiError('image', attempt, imageResult);
    transitions.push(imageError);
    return {
      state: imageError,
      transitions,
    };
  }

  const readyState: MapBootstrapState = {
    phase: 'ready',
    authRequired: false,
    attempt,
    apiBaseUrl: apiBase.normalizedUrl,
    graph: normalized.data,
    image: imageResult.data,
    imageTarget,
  };

  transitions.push(readyState);

  return {
    state: readyState,
    transitions,
  };
}

import type { NavGraph } from '../../src/shared/types';
import { describe, expect, it, vi } from 'vitest';
import type { MapApiClient, MapApiResult, MapImageContract } from '../data/mapApiClient';
import { runMapBootstrap } from './mapBootstrapState';

const BASE_URL = 'https://campusnav.example.com';

function createGraphFixture(): NavGraph {
  return {
    buildings: [
      {
        id: 7,
        name: 'Engineering',
        floors: [
          {
            id: 701,
            floorNumber: 1,
            imagePath: 'floor-plan-7-1.png',
            updatedAt: '2026-01-01T00:00:00.000Z',
            nodes: [
              {
                id: 'entrance-1',
                x: 0.1,
                y: 0.2,
                label: 'Main Entrance',
                type: 'entrance',
                searchable: true,
                floorId: 701,
              },
            ],
            edges: [],
          },
        ],
      },
    ],
  };
}

function mapOkResult(data: NavGraph): MapApiResult<NavGraph> {
  return {
    ok: true,
    endpoint: `${BASE_URL}/api/map`,
    status: 200,
    attempt: 1,
    data,
  };
}

function imageOkResult(): MapApiResult<MapImageContract> {
  return {
    ok: true,
    endpoint: `${BASE_URL}/api/floor-plan/7/1`,
    status: 200,
    attempt: 1,
    data: {
      endpoint: `${BASE_URL}/api/floor-plan/7/1`,
      contentType: 'image/png',
      cacheControl: 'public, max-age=60',
    },
  };
}

function createClient(overrides?: {
  mapResult?: MapApiResult<NavGraph>;
  imageResult?: MapApiResult<MapImageContract>;
}): MapApiClient {
  const mapResult = overrides?.mapResult ?? mapOkResult(createGraphFixture());
  const imageResult = overrides?.imageResult ?? imageOkResult();

  return {
    fetchMapGraph: vi.fn().mockResolvedValue(mapResult),
    fetchFloorPlanImageContract: vi.fn().mockResolvedValue(imageResult),
    fetchCampusImageContract: vi.fn().mockResolvedValue(imageResult),
    resolveMapUrl: () => `${BASE_URL}/api/map`,
    resolveFloorPlanImageUrl: (target) => `${BASE_URL}/api/floor-plan/${target.buildingId}/${target.floorNumber}`,
    resolveCampusImageUrl: () => `${BASE_URL}/api/campus/image`,
  };
}

describe('runMapBootstrap', () => {
  it('transitions loading(map) -> loading(image) -> ready for live graph + image contracts', async () => {
    const client = createClient();

    const result = await runMapBootstrap({
      env: { EXPO_PUBLIC_API_BASE_URL: BASE_URL },
      clientFactory: () => client,
      attempt: 1,
      now: () => 100,
    });

    expect(result.transitions.map((state) => state.phase)).toEqual(['loading', 'loading', 'ready']);
    expect(result.state.phase).toBe('ready');

    if (result.state.phase !== 'ready') {
      throw new Error('Expected ready bootstrap state.');
    }

    expect(result.state.imageTarget).toEqual({ buildingId: 7, floorNumber: 1 });
    expect(result.state.graph.graph.buildings[0]?.name).toBe('Engineering');
    expect(result.state.authRequired).toBe(false);
    expect(client.fetchMapGraph).toHaveBeenCalledTimes(1);
    expect(client.fetchFloorPlanImageContract).toHaveBeenCalledTimes(1);
  });

  it('transitions to map-phase error with endpoint diagnostics when map fetch fails', async () => {
    const client = createClient({
      mapResult: {
        ok: false,
        error: {
          endpoint: `${BASE_URL}/api/map`,
          status: 500,
          reason: 'http-error',
          attempt: 1,
          message: 'Request failed with HTTP 500.',
        },
      },
    });

    const result = await runMapBootstrap({
      env: { EXPO_PUBLIC_API_BASE_URL: BASE_URL },
      clientFactory: () => client,
    });

    expect(result.state.phase).toBe('error');

    if (result.state.phase !== 'error') {
      throw new Error('Expected map-phase bootstrap error.');
    }

    expect(result.state.failedPhase).toBe('map');
    expect(result.state.endpoint).toBe(`${BASE_URL}/api/map`);
    expect(result.state.reason).toBe('http-error');
  });

  it('transitions to image-phase error with timeout diagnostics when image contract fetch fails', async () => {
    const client = createClient({
      imageResult: {
        ok: false,
        error: {
          endpoint: `${BASE_URL}/api/floor-plan/7/1`,
          status: null,
          reason: 'timeout',
          attempt: 2,
          message: 'Request timed out after 2000ms.',
        },
      },
    });

    const result = await runMapBootstrap({
      env: { EXPO_PUBLIC_API_BASE_URL: BASE_URL },
      clientFactory: () => client,
    });

    expect(result.state.phase).toBe('error');

    if (result.state.phase !== 'error') {
      throw new Error('Expected image-phase bootstrap error.');
    }

    expect(result.state.failedPhase).toBe('image');
    expect(result.state.reason).toBe('timeout');
    expect(result.state.endpoint).toContain('/api/floor-plan/7/1');
  });

  it('treats malformed map contracts as unrecoverable bootstrap errors', async () => {
    const client = createClient({
      mapResult: {
        ok: false,
        error: {
          endpoint: `${BASE_URL}/api/map`,
          status: 200,
          reason: 'contract-validation-error',
          attempt: 1,
          message: 'Map payload failed contract validation.',
          details: ['buildings: Required'],
        },
      },
    });

    const result = await runMapBootstrap({
      env: { EXPO_PUBLIC_API_BASE_URL: BASE_URL },
      clientFactory: () => client,
      attempt: 1,
    });

    expect(result.state.phase).toBe('error');

    if (result.state.phase !== 'error') {
      throw new Error('Expected malformed-contract bootstrap error.');
    }

    expect(result.state.failedPhase).toBe('map');
    expect(result.state.reason).toBe('contract-validation-error');
    expect(result.state.recoverable).toBe(false);
  });

  it('supports idempotent restart from error to loading/ready with incremented attempts', async () => {
    const failingClient = createClient({
      mapResult: {
        ok: false,
        error: {
          endpoint: `${BASE_URL}/api/map`,
          status: null,
          reason: 'network-error',
          attempt: 1,
          message: 'Network request failed.',
        },
      },
    });

    const failed = await runMapBootstrap({
      env: { EXPO_PUBLIC_API_BASE_URL: BASE_URL },
      clientFactory: () => failingClient,
      attempt: 1,
      now: () => 1,
    });

    expect(failed.state.phase).toBe('error');

    const healthyClient = createClient();
    const recovered = await runMapBootstrap({
      env: { EXPO_PUBLIC_API_BASE_URL: BASE_URL },
      clientFactory: () => healthyClient,
      attempt: 2,
      now: () => 2,
    });

    expect(recovered.transitions[0]).toMatchObject({
      phase: 'loading',
      currentPhase: 'map',
      attempt: 2,
    });
    expect(recovered.state.phase).toBe('ready');

    if (recovered.state.phase !== 'ready') {
      throw new Error('Expected restart attempt to reach ready state.');
    }

    expect(recovered.state.attempt).toBe(2);
    expect(recovered.state.authRequired).toBe(false);
  });
});

import type { NavGraph } from '../../src/shared/types';
import { validateNavGraphPayload } from '../domain/navGraphSchema';

export type MapApiErrorReason =
  | 'http-error'
  | 'network-error'
  | 'timeout'
  | 'aborted'
  | 'invalid-json'
  | 'contract-validation-error'
  | 'unexpected-content-type';

export interface MapApiError {
  endpoint: string;
  status: number | null;
  reason: MapApiErrorReason;
  attempt: number;
  message: string;
  details?: string[];
}

export type MapApiResult<T> =
  | {
      ok: true;
      endpoint: string;
      status: number;
      attempt: number;
      data: T;
    }
  | {
      ok: false;
      error: MapApiError;
    };

export interface MapImageContract {
  endpoint: string;
  contentType: string;
  cacheControl: string | null;
}

export interface FloorPlanTarget {
  buildingId: number;
  floorNumber: number;
}

export interface MapApiRetryPolicy {
  maxAttempts: number;
  baseDelayMs: number;
  timeoutMs: number;
}

export type Fetcher = (input: string, init?: RequestInit) => Promise<Response>;

export interface MapApiClientConfig {
  baseUrl: string;
  fetchImpl?: Fetcher;
  retryPolicy?: Partial<MapApiRetryPolicy>;
  sleep?: (ms: number) => Promise<void>;
}

export interface MapApiRequestOptions {
  signal?: AbortSignal;
  maxAttempts?: number;
  timeoutMs?: number;
}

interface AttemptSignal {
  signal: AbortSignal;
  cleanup: () => void;
  didTimeout: () => boolean;
}

interface HttpSuccess {
  ok: true;
  endpoint: string;
  attempt: number;
  response: Response;
}

interface HttpFailure {
  ok: false;
  error: MapApiError;
}

const DEFAULT_RETRY_POLICY: MapApiRetryPolicy = {
  maxAttempts: 3,
  baseDelayMs: 200,
  timeoutMs: 2_000,
};

function normalizeBaseUrl(baseUrl: string): string {
  const parsed = new URL(baseUrl);
  parsed.hash = '';
  parsed.search = '';
  return parsed.toString().replace(/\/$/, '');
}

function resolveEndpoint(baseUrl: string, pathname: string): string {
  return new URL(pathname, `${baseUrl}/`).toString();
}

function createApiError(
  endpoint: string,
  attempt: number,
  reason: MapApiErrorReason,
  message: string,
  status: number | null = null,
  details?: string[],
): MapApiError {
  return {
    endpoint,
    status,
    reason,
    attempt,
    message,
    ...(details && details.length > 0 ? { details } : {}),
  };
}

function isRetryableHttpStatus(status: number): boolean {
  return status === 429 || status >= 500;
}

function isAbortError(error: unknown): boolean {
  if (error instanceof DOMException) {
    return error.name === 'AbortError';
  }

  return error instanceof Error && error.name === 'AbortError';
}

function createAttemptSignal(externalSignal: AbortSignal | undefined, timeoutMs: number): AttemptSignal {
  const controller = new AbortController();
  let timeoutTriggered = false;

  const onExternalAbort = () => {
    controller.abort(externalSignal?.reason);
  };

  if (externalSignal) {
    if (externalSignal.aborted) {
      controller.abort(externalSignal.reason);
    } else {
      externalSignal.addEventListener('abort', onExternalAbort, { once: true });
    }
  }

  const timeoutHandle = setTimeout(() => {
    timeoutTriggered = true;
    controller.abort(new Error('timeout'));
  }, timeoutMs);

  const cleanup = () => {
    clearTimeout(timeoutHandle);
    if (externalSignal && !externalSignal.aborted) {
      externalSignal.removeEventListener('abort', onExternalAbort);
    }
  };

  return {
    signal: controller.signal,
    cleanup,
    didTimeout: () => timeoutTriggered,
  };
}

function createSleepWithSignal(
  sleepImpl: (ms: number) => Promise<void>,
  signal: AbortSignal | undefined,
): (ms: number) => Promise<void> {
  return async (ms: number) => {
    if (ms <= 0) {
      return;
    }

    if (!signal) {
      await sleepImpl(ms);
      return;
    }

    if (signal.aborted) {
      throw new DOMException('Aborted', 'AbortError');
    }

    await new Promise<void>((resolve, reject) => {
      const timeoutHandle = setTimeout(() => {
        signal.removeEventListener('abort', onAbort);
        resolve();
      }, ms);

      const onAbort = () => {
        clearTimeout(timeoutHandle);
        reject(new DOMException('Aborted', 'AbortError'));
      };

      signal.addEventListener('abort', onAbort, { once: true });
    });
  };
}

export interface MapApiClient {
  fetchMapGraph(options?: MapApiRequestOptions): Promise<MapApiResult<NavGraph>>;
  fetchFloorPlanImageContract(
    target: FloorPlanTarget,
    options?: MapApiRequestOptions,
  ): Promise<MapApiResult<MapImageContract>>;
  fetchCampusImageContract(options?: MapApiRequestOptions): Promise<MapApiResult<MapImageContract>>;
  resolveMapUrl(): string;
  resolveFloorPlanImageUrl(target: FloorPlanTarget): string;
  resolveCampusImageUrl(): string;
}

export function createMapApiClient(config: MapApiClientConfig): MapApiClient {
  const baseUrl = normalizeBaseUrl(config.baseUrl);
  const fetchImpl: Fetcher =
    config.fetchImpl ?? ((input, init) => fetch(input, init));
  const retryPolicy: MapApiRetryPolicy = {
    ...DEFAULT_RETRY_POLICY,
    ...config.retryPolicy,
  };
  const sleepImpl = config.sleep ?? ((ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms)));

  async function executeGet(
    endpoint: string,
    options: MapApiRequestOptions | undefined,
  ): Promise<HttpSuccess | HttpFailure> {
    const maxAttempts = options?.maxAttempts ?? retryPolicy.maxAttempts;
    const timeoutMs = options?.timeoutMs ?? retryPolicy.timeoutMs;
    const sleepWithSignal = createSleepWithSignal(sleepImpl, options?.signal);

    let lastError: MapApiError | null = null;

    for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
      const attemptSignal = createAttemptSignal(options?.signal, timeoutMs);

      try {
        const response = await fetchImpl(endpoint, {
          method: 'GET',
          signal: attemptSignal.signal as unknown as RequestInit['signal'],
        });

        if (!response.ok) {
          const error = createApiError(
            endpoint,
            attempt,
            'http-error',
            `Request failed with HTTP ${response.status}.`,
            response.status,
          );

          if (attempt < maxAttempts && isRetryableHttpStatus(response.status)) {
            lastError = error;
            const delay = retryPolicy.baseDelayMs * 2 ** (attempt - 1);
            await sleepWithSignal(delay);
            continue;
          }

          return { ok: false, error };
        }

        return {
          ok: true,
          endpoint,
          attempt,
          response,
        };
      } catch (error) {
        const reason: MapApiErrorReason = attemptSignal.didTimeout()
          ? 'timeout'
          : options?.signal?.aborted || isAbortError(error)
            ? 'aborted'
            : 'network-error';

        const apiError = createApiError(
          endpoint,
          attempt,
          reason,
          reason === 'timeout'
            ? `Request timed out after ${timeoutMs}ms.`
            : reason === 'aborted'
              ? 'Request was aborted.'
              : error instanceof Error
                ? error.message
                : 'Network request failed.',
        );

        const shouldRetry = reason !== 'aborted' && attempt < maxAttempts;
        if (shouldRetry) {
          lastError = apiError;
          const delay = retryPolicy.baseDelayMs * 2 ** (attempt - 1);
          await sleepWithSignal(delay);
          continue;
        }

        return { ok: false, error: apiError };
      } finally {
        attemptSignal.cleanup();
      }
    }

    return {
      ok: false,
      error:
        lastError ??
        createApiError(endpoint, maxAttempts, 'network-error', 'Request failed after retries.'),
    };
  }

  async function fetchMapGraph(options?: MapApiRequestOptions): Promise<MapApiResult<NavGraph>> {
    const endpoint = resolveMapEndpoint(baseUrl);
    const responseResult = await executeGet(endpoint, options);

    if (!responseResult.ok) {
      return responseResult;
    }

    let payload: unknown;

    try {
      payload = await responseResult.response.json();
    } catch (error) {
      return {
        ok: false,
        error: createApiError(
          endpoint,
          responseResult.attempt,
          'invalid-json',
          error instanceof Error ? error.message : 'Response body is not valid JSON.',
          responseResult.response.status,
        ),
      };
    }

    const validated = validateNavGraphPayload(payload);
    if (!validated.ok) {
      return {
        ok: false,
        error: createApiError(
          endpoint,
          responseResult.attempt,
          'contract-validation-error',
          validated.error.message,
          responseResult.response.status,
          validated.error.issues,
        ),
      };
    }

    return {
      ok: true,
      endpoint,
      status: responseResult.response.status,
      attempt: responseResult.attempt,
      data: validated.data,
    };
  }

  async function fetchImageContract(
    endpoint: string,
    options?: MapApiRequestOptions,
  ): Promise<MapApiResult<MapImageContract>> {
    const responseResult = await executeGet(endpoint, options);

    if (!responseResult.ok) {
      return responseResult;
    }

    const contentType = responseResult.response.headers.get('content-type');
    if (!contentType || !contentType.toLowerCase().startsWith('image/')) {
      return {
        ok: false,
        error: createApiError(
          endpoint,
          responseResult.attempt,
          'unexpected-content-type',
          `Expected image content-type but received "${contentType ?? 'missing'}".`,
          responseResult.response.status,
        ),
      };
    }

    return {
      ok: true,
      endpoint,
      status: responseResult.response.status,
      attempt: responseResult.attempt,
      data: {
        endpoint,
        contentType,
        cacheControl: responseResult.response.headers.get('cache-control'),
      },
    };
  }

  function resolveMapUrl(): string {
    return resolveMapEndpoint(baseUrl);
  }

  function resolveFloorPlanImageUrl(target: FloorPlanTarget): string {
    return resolveFloorPlanImageEndpoint(baseUrl, target);
  }

  function resolveCampusImageUrl(): string {
    return resolveCampusImageEndpoint(baseUrl);
  }

  async function fetchFloorPlanImageContract(
    target: FloorPlanTarget,
    options?: MapApiRequestOptions,
  ): Promise<MapApiResult<MapImageContract>> {
    return fetchImageContract(resolveFloorPlanImageUrl(target), options);
  }

  async function fetchCampusImageContract(options?: MapApiRequestOptions): Promise<MapApiResult<MapImageContract>> {
    return fetchImageContract(resolveCampusImageUrl(), options);
  }

  return {
    fetchMapGraph,
    fetchFloorPlanImageContract,
    fetchCampusImageContract,
    resolveMapUrl,
    resolveFloorPlanImageUrl,
    resolveCampusImageUrl,
  };
}

export function resolveMapEndpoint(baseUrl: string): string {
  const normalizedBaseUrl = normalizeBaseUrl(baseUrl);
  return resolveEndpoint(normalizedBaseUrl, '/api/map');
}

export function resolveFloorPlanImageEndpoint(baseUrl: string, target: FloorPlanTarget): string {
  const normalizedBaseUrl = normalizeBaseUrl(baseUrl);
  const buildingId = Number(target.buildingId);
  const floorNumber = Number(target.floorNumber);
  return resolveEndpoint(normalizedBaseUrl, `/api/floor-plan/${buildingId}/${floorNumber}`);
}

export function resolveCampusImageEndpoint(baseUrl: string): string {
  const normalizedBaseUrl = normalizeBaseUrl(baseUrl);
  return resolveEndpoint(normalizedBaseUrl, '/api/campus/image');
}

