    expect(resolveFloorPlanImageEndpoint('https://campusnav.example.com', { buildingId: 4, floorNumber: 2 })).toBe(
      'https://campusnav.example.com/api/floor-plan/4/2',
    );
    expect(resolveCampusImageEndpoint('https://campusnav.example.com')).toBe(
      'https://campusnav.example.com/api/campus/image',
    );
  });

  it('fetches and validates map payload successfully', async () => {
    const payload = createGraphFixture();
    const fetchImpl = vi.fn<Fetcher>().mockResolvedValue(
      new Response(JSON.stringify(payload), {
        status: 200,
        headers: {
          'content-type': 'application/json',
        },
      }),
    );

    const client = createMapApiClient({
      baseUrl: 'https://campusnav.example.com',
      fetchImpl,
      retryPolicy: { maxAttempts: 2, baseDelayMs: 0 },
    });

    const result = await client.fetchMapGraph();

    expect(result.ok).toBe(true);
    if (!result.ok) {
      throw new Error('Expected map request to succeed.');
    }

    expect(result.endpoint).toBe('https://campusnav.example.com/api/map');
    expect(result.status).toBe(200);
    expect(result.attempt).toBe(1);
    expect(result.data.buildings[0]?.floors[0]?.nodes[1]?.connectsToNodeAboveId).toBe('stairs-2');
    expect(fetchImpl).toHaveBeenCalledTimes(1);
  });

  it('retries retryable HTTP failures and reports successful attempt count', async () => {
    const payload = createGraphFixture();
    const fetchImpl = vi
      .fn<Fetcher>()
      .mockResolvedValueOnce(new Response('service unavailable', { status: 500 }))
      .mockResolvedValueOnce(
        new Response(JSON.stringify(payload), {
          status: 200,
          headers: {
            'content-type': 'application/json',
          },
        }),
      );

    const client = createMapApiClient({
      baseUrl: 'https://campusnav.example.com',
      fetchImpl,
      retryPolicy: { maxAttempts: 3, baseDelayMs: 0 },
    });

    const result = await client.fetchMapGraph();

    expect(result.ok).toBe(true);
    if (!result.ok) {
      throw new Error('Expected map request to succeed after retry.');
    }

    expect(result.attempt).toBe(2);
    expect(fetchImpl).toHaveBeenCalledTimes(2);
  });

  it('returns structured endpoint/status/reason metadata for non-retryable HTTP errors', async () => {
    const fetchImpl = vi.fn<Fetcher>().mockResolvedValue(new Response('missing', { status: 404 }));
    const client = createMapApiClient({
      baseUrl: 'https://campusnav.example.com',
      fetchImpl,
      retryPolicy: { maxAttempts: 3, baseDelayMs: 0 },
    });

    const result = await client.fetchMapGraph();

    expect(result.ok).toBe(false);
    if (result.ok) {
      throw new Error('Expected HTTP failure.');
    }

    expect(result.error.endpoint).toBe('https://campusnav.example.com/api/map');
    expect(result.error.status).toBe(404);
    expect(result.error.reason).toBe('http-error');
    expect(result.error.attempt).toBe(1);
    expect(fetchImpl).toHaveBeenCalledTimes(1);
  });

  it('classifies timeout failures after bounded retries', async () => {
    const timeoutFetch = vi.fn<Fetcher>((_input, init) => {
      return new Promise<Response>((_, reject) => {
        init?.signal?.addEventListener(
          'abort',
          () => reject(new DOMException('Aborted', 'AbortError')),
          { once: true },
        );
      });
    });

    const client = createMapApiClient({
      baseUrl: 'https://campusnav.example.com',
      fetchImpl: timeoutFetch,
      retryPolicy: { maxAttempts: 2, baseDelayMs: 0, timeoutMs: 5 },
    });

    const result = await client.fetchMapGraph();

    expect(result.ok).toBe(false);
    if (result.ok) {
      throw new Error('Expected timeout failure.');
    }

    expect(result.error.reason).toBe('timeout');
    expect(result.error.attempt).toBe(2);
    expect(result.error.status).toBeNull();
    expect(timeoutFetch).toHaveBeenCalledTimes(2);
  });

  it('classifies caller cancellation as aborted without extra retries', async () => {
    const abortingFetch = vi.fn<Fetcher>((_input, init) => {
      return new Promise<Response>((_, reject) => {
        const signal = init?.signal;

        if (signal?.aborted) {
          reject(new DOMException('Aborted', 'AbortError'));
          return;
        }

        signal?.addEventListener(
          'abort',
          () => reject(new DOMException('Aborted', 'AbortError')),
          { once: true },
        );
      });
    });

    const client = createMapApiClient({
      baseUrl: 'https://campusnav.example.com',
      fetchImpl: abortingFetch,
      retryPolicy: { maxAttempts: 3, baseDelayMs: 0, timeoutMs: 50 },
    });

    const controller = new AbortController();
    controller.abort();

    const result = await client.fetchMapGraph({ signal: controller.signal });

    expect(result.ok).toBe(false);
    if (result.ok) {
      throw new Error('Expected aborted request result.');
    }

    expect(result.error.reason).toBe('aborted');
    expect(result.error.attempt).toBe(1);
    expect(abortingFetch).toHaveBeenCalledTimes(1);
  });

  it('returns invalid-json when response body cannot be parsed as JSON', async () => {
    const fetchImpl = vi.fn<Fetcher>().mockResolvedValue(
      new Response('this is not json', {
        status: 200,
        headers: { 'content-type': 'application/json' },
      }),
    );

    const client = createMapApiClient({ baseUrl: 'https://campusnav.example.com', fetchImpl });
    const result = await client.fetchMapGraph();

    expect(result.ok).toBe(false);
    if (result.ok) {
      throw new Error('Expected invalid JSON failure.');
    }

    expect(result.error.reason).toBe('invalid-json');
    expect(result.error.status).toBe(200);
    expect(result.error.endpoint).toContain('/api/map');
  });

  it('returns contract-validation-error with details for malformed map payloads', async () => {
    const fetchImpl = vi.fn<Fetcher>().mockResolvedValue(
      new Response(JSON.stringify({ foo: 'bar' }), {
        status: 200,
        headers: { 'content-type': 'application/json' },
      }),
    );

    const client = createMapApiClient({ baseUrl: 'https://campusnav.example.com', fetchImpl });
    const result = await client.fetchMapGraph();

    expect(result.ok).toBe(false);
    if (result.ok) {
      throw new Error('Expected contract validation failure.');
    }

    expect(result.error.reason).toBe('contract-validation-error');
    expect(result.error.details?.[0]).toContain('buildings');
    expect(result.error.endpoint).toBe('https://campusnav.example.com/api/map');
  });

  it('returns unexpected-content-type for image contract endpoints with non-image responses', async () => {
    const fetchImpl = vi.fn<Fetcher>().mockResolvedValue(
      new Response('not image', {
        status: 200,
        headers: {
          'content-type': 'application/json',
        },
      }),
    );

    const client = createMapApiClient({ baseUrl: 'https://campusnav.example.com', fetchImpl });
    const result = await client.fetchCampusImageContract();

    expect(result.ok).toBe(false);
    if (result.ok) {
      throw new Error('Expected image content-type failure.');
    }

    expect(result.error.reason).toBe('unexpected-content-type');
    expect(result.error.endpoint).toBe('https://campusnav.example.com/api/campus/image');
    expect(result.error.status).toBe(200);
  });
});

import type { NavBuilding, NavEdge, NavFloor, NavGraph, NavNode } from '../../src/shared/types';
import {
  type NavGraphContractValidationError,
  validateNavGraphPayload,
} from './navGraphSchema';

export interface NormalizedFloorRecord {
  buildingId: number;
  buildingName: string;
  floor: NavFloor;
}

export interface NormalizedNodeRecord {
  buildingId: number;
  buildingName: string;
  floorId: number;
  floorNumber: number;
  node: NavNode;
}

export interface NormalizedEdgeRecord {
  buildingId: number;
  floorId: number;
  edge: NavEdge;
  effectiveAccessibleWeight: number;
}

export interface NormalizedNavGraph {
  graph: NavGraph;
  buildingById: Map<number, NavBuilding>;
  floorById: Map<number, NormalizedFloorRecord>;
  floorByBuildingAndNumber: Map<string, NormalizedFloorRecord>;
  nodeById: Map<string, NormalizedNodeRecord>;
  edgeById: Map<string, NormalizedEdgeRecord>;
  outgoingEdgesByNodeId: Map<string, NormalizedEdgeRecord[]>;
}

export type NavGraphNormalizationErrorCode =
  | 'duplicate-building-id'
  | 'duplicate-floor-id'
  | 'duplicate-floor-number-per-building'
  | 'duplicate-node-id'
  | 'duplicate-edge-id'
  | 'node-floor-mismatch'
  | 'edge-node-missing';

export interface NavGraphNormalizationError {
  reason: 'normalization-failure';
  code: NavGraphNormalizationErrorCode;
  message: string;
}

export type NavGraphNormalizationResult =
  | { ok: true; data: NormalizedNavGraph }
  | { ok: false; error: NavGraphNormalizationError };

export type NavGraphParseAndNormalizeResult =
  | { ok: true; data: NormalizedNavGraph }
  | { ok: false; error: NavGraphContractValidationError | NavGraphNormalizationError };

function fail(
  code: NavGraphNormalizationErrorCode,
  message: string,
): { ok: false; error: NavGraphNormalizationError } {
  return {
    ok: false,
    error: {
      reason: 'normalization-failure',
      code,
      message,
    },
  };
}

export function floorLookupKey(buildingId: number, floorNumber: number): string {
  return `${buildingId}:${floorNumber}`;
}

export function getEffectiveAccessibleWeight(edge: Pick<NavEdge, 'accessible' | 'accessibleWeight'>): number {
  return edge.accessible ? edge.accessibleWeight : Number.POSITIVE_INFINITY;
}

export function normalizeNavGraph(graph: NavGraph): NavGraphNormalizationResult {
  const buildingById = new Map<number, NavBuilding>();
  const floorById = new Map<number, NormalizedFloorRecord>();
  const floorByBuildingAndNumber = new Map<string, NormalizedFloorRecord>();
  const nodeById = new Map<string, NormalizedNodeRecord>();
  const edgeById = new Map<string, NormalizedEdgeRecord>();
  const outgoingEdgesByNodeId = new Map<string, NormalizedEdgeRecord[]>();

  for (const building of graph.buildings) {
    if (buildingById.has(building.id)) {
      return fail('duplicate-building-id', `Duplicate building id detected: ${building.id}.`);
    }

    buildingById.set(building.id, building);

    for (const floor of building.floors) {
      if (floorById.has(floor.id)) {
        return fail('duplicate-floor-id', `Duplicate floor id detected: ${floor.id}.`);
      }

      const floorKey = floorLookupKey(building.id, floor.floorNumber);
      if (floorByBuildingAndNumber.has(floorKey)) {
        return fail(
          'duplicate-floor-number-per-building',
          `Duplicate floor number ${floor.floorNumber} for building ${building.id}.`,
        );
      }

      const floorRecord: NormalizedFloorRecord = {
        buildingId: building.id,
        buildingName: building.name,
        floor,
      };

      floorById.set(floor.id, floorRecord);
      floorByBuildingAndNumber.set(floorKey, floorRecord);

      for (const node of floor.nodes) {
        if (node.floorId !== floor.id) {
          return fail(
            'node-floor-mismatch',
            `Node ${node.id} reports floorId=${node.floorId}, expected ${floor.id}.`,
          );
        }

        if (nodeById.has(node.id)) {
          return fail('duplicate-node-id', `Duplicate node id detected: ${node.id}.`);
        }

        nodeById.set(node.id, {
          buildingId: building.id,
          buildingName: building.name,
          floorId: floor.id,
          floorNumber: floor.floorNumber,
          node,
        });
      }

      for (const edge of floor.edges) {
        if (edgeById.has(edge.id)) {
          return fail('duplicate-edge-id', `Duplicate edge id detected: ${edge.id}.`);
        }

        const edgeRecord: NormalizedEdgeRecord = {
          buildingId: building.id,
          floorId: floor.id,
          edge,
          effectiveAccessibleWeight: getEffectiveAccessibleWeight(edge),
        };

        edgeById.set(edge.id, edgeRecord);
      }
    }
  }

  for (const edgeRecord of edgeById.values()) {
    const source = nodeById.get(edgeRecord.edge.sourceId);
    const target = nodeById.get(edgeRecord.edge.targetId);

    if (!source || !target) {
      return fail(
        'edge-node-missing',
        `Edge ${edgeRecord.edge.id} references missing node(s): ${edgeRecord.edge.sourceId} -> ${edgeRecord.edge.targetId}.`,
      );
    }

    const currentOutgoing = outgoingEdgesByNodeId.get(source.node.id) ?? [];
    currentOutgoing.push(edgeRecord);
    outgoingEdgesByNodeId.set(source.node.id, currentOutgoing);
  }

  return {
    ok: true,
    data: {
      graph,
      buildingById,
      floorById,
      floorByBuildingAndNumber,
      nodeById,
      edgeById,
      outgoingEdgesByNodeId,
    },
  };
}

export function parseAndNormalizeNavGraph(payload: unknown): NavGraphParseAndNormalizeResult {
  const validated = validateNavGraphPayload(payload);
  if (!validated.ok) {
    return validated;
  }

  return normalizeNavGraph(validated.data);
}

import type { NavGraph } from '../../src/shared/types';
import { z } from 'zod';

const navNodeTypeValues = [
  'room',
  'entrance',
  'elevator',
  'stairs',
  'ramp',
  'restroom',
  'junction',
  'hallway',
  'landmark',
] as const;

const finiteNumber = z.number().finite();
const normalizedCoordinate = finiteNumber.min(0).max(1);
const positiveInt = z.number().int().positive();

const navFloorGpsBoundsSchema = z
  .object({
    minLat: finiteNumber,
    maxLat: finiteNumber,
    minLng: finiteNumber,
    maxLng: finiteNumber,
  })
  .strict()
  .refine((bounds) => bounds.minLat < bounds.maxLat && bounds.minLng < bounds.maxLng, {
    message: 'gpsBounds must satisfy minLat < maxLat and minLng < maxLng',
  });

const navNodeSchema = z
  .object({
    id: z.string().min(1),
    x: normalizedCoordinate,
    y: normalizedCoordinate,
    label: z.string(),
    type: z.enum(navNodeTypeValues),
    searchable: z.boolean(),
    floorId: positiveInt,
    roomNumber: z.string().optional(),
    description: z.string().optional(),
    accessibilityNotes: z.string().optional(),
    connectsToFloorAboveId: positiveInt.optional(),
    connectsToFloorBelowId: positiveInt.optional(),
    connectsToNodeAboveId: z.string().min(1).optional(),
    connectsToNodeBelowId: z.string().min(1).optional(),
    connectsToBuildingId: positiveInt.optional(),
  })
  .strict();

const navEdgeSchema = z
  .object({
    id: z.string().min(1),
    sourceId: z.string().min(1),
    targetId: z.string().min(1),
    standardWeight: finiteNumber.min(0),
    accessibleWeight: finiteNumber.min(0),
    accessible: z.boolean(),
    bidirectional: z.boolean(),
    accessibilityNotes: z.string().optional(),
  })
  .strict();

const navFloorSchema = z
  .object({
    id: positiveInt,
    floorNumber: z.number().int(),
    imagePath: z.string().min(1),
    updatedAt: z.string().min(1),
    gpsBounds: navFloorGpsBoundsSchema.optional(),
    nodes: z.array(navNodeSchema),
    edges: z.array(navEdgeSchema),
  })
  .strict();

const navBuildingSchema = z
  .object({
    id: positiveInt,
    name: z.string().min(1),
    floors: z.array(navFloorSchema),
  })
  .strict();

export const navGraphContractSchema = z
  .object({
    buildings: z.array(navBuildingSchema),
  })
  .strict();

export type NavGraphContract = z.output<typeof navGraphContractSchema>;

export interface NavGraphContractValidationError {
  reason: 'contract-validation-error';
  message: string;
  issues: string[];
}

export type NavGraphValidationResult =
  | { ok: true; data: NavGraph }
  | { ok: false; error: NavGraphContractValidationError };

function formatIssuePath(path: PropertyKey[]): string {
  if (path.length === 0) {
    return 'root';
  }

  return path
    .map((segment) => {
      if (typeof segment === 'number') {
        return `[${segment}]`;
      }

      return typeof segment === 'symbol' ? segment.toString() : segment;
    })
    .join('.');
}

export function validateNavGraphPayload(payload: unknown): NavGraphValidationResult {
  const parsed = navGraphContractSchema.safeParse(payload);

  if (!parsed.success) {
    const issues = parsed.error.issues.map((issue) => `${formatIssuePath(issue.path)}: ${issue.message}`);

    return {
      ok: false,
      error: {
        reason: 'contract-validation-error',
        message: 'Map payload failed contract validation.',
        issues,
      },
    };
  }

  const data: NavGraph = parsed.data;

  return {
    ok: true,
    data,
  };
}

export interface ViewportPoint {
  x: number;
  y: number;
}

export interface ViewportDimensions {
  width: number;
  height: number;
}

export interface MapTransform {
  scale: number;
  rotationDeg: number;
  translation: ViewportPoint;
}

export interface PinchRotateInput {
  scaleFactor: number;
  rotationDeltaDeg: number;
  focal: ViewportPoint;
  viewport: ViewportDimensions | null | undefined;
}

export const MIN_VIEWPORT_SCALE = 0.5;
export const MAX_VIEWPORT_SCALE = 4;

const DEFAULT_TRANSFORM: MapTransform = {
  scale: 1,
  rotationDeg: 0,
  translation: { x: 0, y: 0 },
};

const EPSILON = 1e-6;

function isFiniteNumber(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value);
}

function toRadians(degrees: number): number {
  return (degrees * Math.PI) / 180;
}

function rotatePoint(point: ViewportPoint, angleRad: number): ViewportPoint {
  const cos = Math.cos(angleRad);
  const sin = Math.sin(angleRad);

  return {
    x: point.x * cos - point.y * sin,
    y: point.x * sin + point.y * cos,
  };
}

function clamp(value: number, min: number, max: number): number {
  return Math.min(Math.max(value, min), max);
}

function isValidViewport(viewport: ViewportDimensions | null | undefined): viewport is ViewportDimensions {
  return (
    !!viewport &&
    isFiniteNumber(viewport.width) &&
    isFiniteNumber(viewport.height) &&
    viewport.width > 0 &&
    viewport.height > 0
  );
}

function clampFocalPoint(focal: ViewportPoint, viewport: ViewportDimensions): ViewportPoint {
  if (!isFiniteNumber(focal.x) || !isFiniteNumber(focal.y)) {
    return {
      x: viewport.width / 2,
      y: viewport.height / 2,
    };
  }

  return {
    x: clamp(focal.x, 0, viewport.width),
    y: clamp(focal.y, 0, viewport.height),
  };
}

export function createInitialMapTransform(): MapTransform {
  return {
    scale: DEFAULT_TRANSFORM.scale,
    rotationDeg: DEFAULT_TRANSFORM.rotationDeg,
    translation: { ...DEFAULT_TRANSFORM.translation },
  };
}

export function clampViewportScale(scale: number): number {
  if (!isFiniteNumber(scale)) {
    return DEFAULT_TRANSFORM.scale;
  }

  return clamp(scale, MIN_VIEWPORT_SCALE, MAX_VIEWPORT_SCALE);
}

export function normalizeRotationDeg(rotationDeg: number): number {
  if (!isFiniteNumber(rotationDeg)) {
    return DEFAULT_TRANSFORM.rotationDeg;
  }

  return ((((rotationDeg + 180) % 360) + 360) % 360) - 180;
}

export function worldFromScreen(screenPoint: ViewportPoint, transform: MapTransform): ViewportPoint {
  const scale = clampViewportScale(transform.scale);
  const normalizedRotation = normalizeRotationDeg(transform.rotationDeg);

  const translated = {
    x: screenPoint.x - transform.translation.x,
    y: screenPoint.y - transform.translation.y,
  };

  const unrotated = rotatePoint(translated, -toRadians(normalizedRotation));

  return {
    x: unrotated.x / scale,
    y: unrotated.y / scale,
  };
}

export function screenFromWorld(worldPoint: ViewportPoint, transform: MapTransform): ViewportPoint {
  const scale = clampViewportScale(transform.scale);
  const normalizedRotation = normalizeRotationDeg(transform.rotationDeg);

  const scaled = {
    x: worldPoint.x * scale,
    y: worldPoint.y * scale,
  };

  const rotated = rotatePoint(scaled, toRadians(normalizedRotation));

  return {
    x: rotated.x + transform.translation.x,
    y: rotated.y + transform.translation.y,
  };
}

export function applyPanDelta(transform: MapTransform, delta: ViewportPoint): MapTransform {
  if (!isFiniteNumber(delta.x) || !isFiniteNumber(delta.y)) {
    return transform;
  }

  const nextTranslation = {
    x: transform.translation.x + delta.x,
    y: transform.translation.y + delta.y,
  };

  if (!isFiniteNumber(nextTranslation.x) || !isFiniteNumber(nextTranslation.y)) {
    return transform;
  }

  return {
    ...transform,
    translation: nextTranslation,
  };
}

export function applyPinchRotate(transform: MapTransform, input: PinchRotateInput): MapTransform {
  if (!isValidViewport(input.viewport)) {
    return transform;
  }

  if (
    !isFiniteNumber(input.scaleFactor) ||
    !isFiniteNumber(input.rotationDeltaDeg) ||
    input.scaleFactor <= 0
  ) {
    return transform;
  }

  const focalPoint = clampFocalPoint(input.focal, input.viewport);
  const worldAnchor = worldFromScreen(focalPoint, transform);

  const nextScale = clampViewportScale(transform.scale * input.scaleFactor);
  const nextRotation = normalizeRotationDeg(transform.rotationDeg + input.rotationDeltaDeg);

  const projectedAnchor = screenFromWorld(worldAnchor, {
    scale: nextScale,
    rotationDeg: nextRotation,
    translation: { x: 0, y: 0 },
  });

  const nextTranslation = {
    x: focalPoint.x - projectedAnchor.x,
    y: focalPoint.y - projectedAnchor.y,
  };

  if (!isFiniteNumber(nextTranslation.x) || !isFiniteNumber(nextTranslation.y)) {
    return transform;
  }

  return {
    scale: nextScale,
    rotationDeg: nextRotation,
    translation: nextTranslation,
  };
}

export function mapTransformsEqual(a: MapTransform, b: MapTransform): boolean {
  return (
    Math.abs(a.scale - b.scale) < EPSILON &&
    Math.abs(a.rotationDeg - b.rotationDeg) < EPSILON &&
    Math.abs(a.translation.x - b.translation.x) < EPSILON &&
    Math.abs(a.translation.y - b.translation.y) < EPSILON
  );
}

import { describe, expect, it } from 'vitest';

import {
  MAX_VIEWPORT_SCALE,
  MIN_VIEWPORT_SCALE,
  applyPanDelta,
  applyPinchRotate,
  clampViewportScale,
  createInitialMapTransform,
  mapTransformsEqual,
  normalizeRotationDeg,
  screenFromWorld,
  worldFromScreen,
  type MapTransform,
} from './mapTransform';

const EPSILON = 1e-6;

function approximatelyEqual(a: number, b: number): boolean {
  return Math.abs(a - b) < EPSILON;
}

describe('mapTransform', () => {
  it('anchors focal point under pinch+rotate transforms without drift', () => {
    const transform: MapTransform = {
      scale: 1.4,
      rotationDeg: 25,
      translation: { x: 40, y: -30 },
    };
    const focal = { x: 210, y: 160 };
    const worldAnchor = worldFromScreen(focal, transform);

    const next = applyPinchRotate(transform, {
      scaleFactor: 1.3,
      rotationDeltaDeg: 22,
      focal,
      viewport: { width: 360, height: 640 },
    });

    const mapped = screenFromWorld(worldAnchor, next);

    expect(approximatelyEqual(mapped.x, focal.x)).toBe(true);
    expect(approximatelyEqual(mapped.y, focal.y)).toBe(true);
  });

  it('normalizes wraparound rotation into [-180, 180)', () => {
    expect(normalizeRotationDeg(185)).toBe(-175);
    expect(normalizeRotationDeg(-181)).toBe(179);

    const wrapped = applyPinchRotate(
      {
        scale: 1,
        rotationDeg: 179,
        translation: { x: 0, y: 0 },
      },
      {
        scaleFactor: 1,
        rotationDeltaDeg: 5,
        focal: { x: 120, y: 80 },
        viewport: { width: 240, height: 240 },
      },
    );

    expect(wrapped.rotationDeg).toBe(-176);
  });

  it('clamps zoom to min and max bounds', () => {
    const zoomedOut = clampViewportScale(0.01);
    const zoomedIn = clampViewportScale(99);

    expect(zoomedOut).toBe(MIN_VIEWPORT_SCALE);
    expect(zoomedIn).toBe(MAX_VIEWPORT_SCALE);

    const transform = {
      scale: 3.9,
      rotationDeg: 0,
      translation: { x: 0, y: 0 },
    };

    const next = applyPinchRotate(transform, {
      scaleFactor: 2,
      rotationDeltaDeg: 0,
      focal: { x: 80, y: 80 },
      viewport: { width: 160, height: 160 },
    });

    expect(next.scale).toBe(MAX_VIEWPORT_SCALE);
  });

  it('ignores malformed gesture frames (NaN/Infinity/missing viewport) and keeps stable transform', () => {
    const stable = {
      scale: 1.2,
      rotationDeg: 15,
      translation: { x: 10, y: 12 },
    };

    const nextNaNScale = applyPinchRotate(stable, {
      scaleFactor: Number.NaN,
      rotationDeltaDeg: 0,
      focal: { x: 10, y: 10 },
      viewport: { width: 100, height: 100 },
    });

    const nextInfinityRotation = applyPinchRotate(stable, {
      scaleFactor: 1,
      rotationDeltaDeg: Number.POSITIVE_INFINITY,
      focal: { x: 10, y: 10 },
      viewport: { width: 100, height: 100 },
    });

    const nextMissingViewport = applyPinchRotate(stable, {
      scaleFactor: 1.1,
      rotationDeltaDeg: 5,
      focal: { x: 10, y: 10 },
      viewport: undefined,
    });

    expect(mapTransformsEqual(nextNaNScale, stable)).toBe(true);
    expect(mapTransformsEqual(nextInfinityRotation, stable)).toBe(true);
    expect(mapTransformsEqual(nextMissingViewport, stable)).toBe(true);
  });

  it('applies pan deltas and rejects malformed pan inputs', () => {
    const transform = createInitialMapTransform();

    const panned = applyPanDelta(transform, { x: 24, y: -16 });
    expect(panned.translation).toEqual({ x: 24, y: -16 });

    const malformed = applyPanDelta(panned, { x: Number.NaN, y: 3 });
    expect(mapTransformsEqual(malformed, panned)).toBe(true);
  });
});

import type { NavGraph } from '../../src/shared/types';
import { describe, expect, it } from 'vitest';
import {
  floorLookupKey,
  getEffectiveAccessibleWeight,
  normalizeNavGraph,
  parseAndNormalizeNavGraph,
} from './navGraph';
import { validateNavGraphPayload } from './navGraphSchema';

function createValidGraph(): NavGraph {
  return {
    buildings: [
      {
        id: 1,
        name: 'Engineering',
        floors: [
          {
            id: 11,
            floorNumber: 1,
            imagePath: 'engineering-floor-1.png',
            updatedAt: '2026-01-01T00:00:00.000Z',
            nodes: [
              {
                id: 'entrance-1',
                x: 0.1,
                y: 0.2,
                label: 'Main Entrance',
                type: 'entrance',
                searchable: true,
                floorId: 11,
              },
              {
                id: 'stairs-1',
                x: 0.5,
                y: 0.4,
                label: 'Stairs',
                type: 'stairs',
                searchable: false,
                floorId: 11,
                connectsToFloorAboveId: 12,
                connectsToNodeAboveId: 'stairs-2',
              },
            ],
            edges: [
              {
                id: 'edge-1',
                sourceId: 'entrance-1',
                targetId: 'stairs-1',
                standardWeight: 0.3,
                accessibleWeight: 10000000000,
                accessible: false,
                bidirectional: true,
              },
            ],
          },
          {
            id: 12,
            floorNumber: 2,
            imagePath: 'engineering-floor-2.png',
            updatedAt: '2026-01-01T00:00:00.000Z',
            gpsBounds: {
              minLat: 10,
              maxLat: 11,
              minLng: 20,
              maxLng: 21,
            },
            nodes: [
              {
                id: 'stairs-2',
                x: 0.5,
                y: 0.4,
                label: 'Stairs (Floor 2)',
                type: 'stairs',
                searchable: false,
                floorId: 12,
                connectsToFloorBelowId: 11,
                connectsToNodeBelowId: 'stairs-1',
              },
            ],
            edges: [],
          },
        ],
      },
    ],
  };
}

describe('navGraphSchema + navGraph normalization', () => {
  it('validates and normalizes graph payloads into lookup maps', () => {
    const graph = createValidGraph();
    const parsed = validateNavGraphPayload(graph);

    expect(parsed.ok).toBe(true);
    if (!parsed.ok) {
      throw new Error('Expected graph payload to pass contract validation.');
    }

    const normalized = normalizeNavGraph(parsed.data);

    expect(normalized.ok).toBe(true);
    if (!normalized.ok) {
      throw new Error(`Expected normalization success. Received: ${normalized.error.message}`);
    }

    expect(normalized.data.buildingById.get(1)?.name).toBe('Engineering');
    expect(normalized.data.floorById.get(12)?.floor.gpsBounds?.maxLng).toBe(21);
    expect(normalized.data.floorByBuildingAndNumber.get(floorLookupKey(1, 2))?.floor.id).toBe(12);
    expect(normalized.data.nodeById.get('stairs-2')?.floorNumber).toBe(2);
    expect(normalized.data.outgoingEdgesByNodeId.get('entrance-1')?.length).toBe(1);
  });

  it('preserves optional connector omission for non-connector nodes', () => {
    const normalized = parseAndNormalizeNavGraph(createValidGraph());

    expect(normalized.ok).toBe(true);
    if (!normalized.ok) {
      throw new Error(`Expected parse+normalize success. Received: ${normalized.error.message}`);
    }

    const entrance = normalized.data.nodeById.get('entrance-1')?.node;
    expect(entrance).toBeDefined();
    expect(Object.prototype.hasOwnProperty.call(entrance, 'connectsToFloorAboveId')).toBe(false);
    expect(Object.prototype.hasOwnProperty.call(entrance, 'connectsToNodeAboveId')).toBe(false);
  });

  it('preserves non-accessible edge semantics via effective accessible weight', () => {
    const normalized = parseAndNormalizeNavGraph(createValidGraph());

    expect(normalized.ok).toBe(true);
    if (!normalized.ok) {
      throw new Error(`Expected parse+normalize success. Received: ${normalized.error.message}`);
    }

    const edgeRecord = normalized.data.edgeById.get('edge-1');
    expect(edgeRecord).toBeDefined();
    expect(edgeRecord?.edge.accessibleWeight).toBe(10000000000);
    expect(edgeRecord?.effectiveAccessibleWeight).toBe(Number.POSITIVE_INFINITY);
    expect(getEffectiveAccessibleWeight(edgeRecord!.edge)).toBe(Number.POSITIVE_INFINITY);
  });

  it('accepts empty building lists as a valid boundary case', () => {
    const parsed = validateNavGraphPayload({ buildings: [] });
    expect(parsed.ok).toBe(true);

    if (!parsed.ok) {
      throw new Error('Expected empty building list to validate.');
    }

    const normalized = normalizeNavGraph(parsed.data);
    expect(normalized.ok).toBe(true);

    if (!normalized.ok) {
      throw new Error('Expected empty graph to normalize.');
    }

    expect(normalized.data.buildingById.size).toBe(0);
    expect(normalized.data.nodeById.size).toBe(0);
  });

  it('reports malformed payloads with contract-validation-error details', () => {
    const malformedPayload = {
      buildings: [
        {
          id: 1,
          name: 'Engineering',
          floors: [
            {
              id: 11,
              floorNumber: 'one',
              imagePath: 'engineering-floor-1.png',
              updatedAt: '2026-01-01T00:00:00.000Z',
              nodes: [
                {
                  id: 'room-101',
                  x: '0.3',
                  y: 0.4,
                  label: 'Room 101',
                  type: 'room',
                  searchable: true,
                  floorId: 11,
                },
              ],
              edges: [],
            },
          ],
        },
      ],
    };

    const result = validateNavGraphPayload(malformedPayload);

    expect(result.ok).toBe(false);
    if (result.ok) {
      throw new Error('Expected malformed payload validation failure.');
    }

    expect(result.error.reason).toBe('contract-validation-error');
    expect(result.error.issues.some((issue) => issue.includes('floorNumber'))).toBe(true);
    expect(result.error.issues.some((issue) => issue.includes('x'))).toBe(true);
  });

  it('fails normalization when duplicate node ids are present', () => {
    const duplicateNodeGraph = createValidGraph();
    duplicateNodeGraph.buildings[0]!.floors[1]!.nodes.push({
      id: 'entrance-1',
      x: 0.8,
      y: 0.8,
      label: 'Duplicate',
      type: 'junction',
      searchable: false,
      floorId: 12,
    });

    const result = parseAndNormalizeNavGraph(duplicateNodeGraph);

    expect(result.ok).toBe(false);
    if (result.ok) {
      throw new Error('Expected duplicate-node-id failure.');
    }

    expect(result.error.reason).toBe('normalization-failure');
    if (result.error.reason !== 'normalization-failure') {
      throw new Error('Expected normalization failure error type.');
    }

    expect(result.error.code).toBe('duplicate-node-id');
  });

  it('fails normalization when an edge references a missing node', () => {
    const brokenGraph = createValidGraph();
    brokenGraph.buildings[0]!.floors[0]!.edges.push({
      id: 'edge-missing-node',
      sourceId: 'does-not-exist',
      targetId: 'stairs-1',
      standardWeight: 1,
      accessibleWeight: 1,
      accessible: true,
      bidirectional: false,
    });

    const result = parseAndNormalizeNavGraph(brokenGraph);

    expect(result.ok).toBe(false);
    if (result.ok) {
      throw new Error('Expected edge-node-missing failure.');
    }

    expect(result.error.reason).toBe('normalization-failure');
    if (result.error.reason !== 'normalization-failure') {
      throw new Error('Expected normalization failure error type.');
    }

    expect(result.error.code).toBe('edge-node-missing');
  });

  it('rejects payloads missing buildings', () => {
    const result = validateNavGraphPayload({});

    expect(result.ok).toBe(false);
    if (result.ok) {
      throw new Error('Expected missing-buildings validation failure.');
    }

    expect(result.error.reason).toBe('contract-validation-error');
    expect(result.error.issues.some((issue) => issue.includes('buildings'))).toBe(true);
  });
});

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  Image,
  PanResponder,
  Pressable,
  StyleSheet,
  Text,
  View,
  type LayoutChangeEvent,
  type PanResponderInstance,
} from 'react-native';

import {
  applyPanDelta,
  applyPinchRotate,
  createInitialMapTransform,
  mapTransformsEqual,
  type MapTransform,
  type ViewportDimensions,
  type ViewportPoint,
} from './mapTransform';

interface MapViewportProps {
  imageUri: string;
  onTransformChange?: (transform: MapTransform) => void;
}

interface GestureTracking {
  mode: 'none' | 'pan' | 'pinch';
  lastPanPoint: ViewportPoint | null;
  pinchStartDistance: number;
  pinchStartAngle: number;
  pinchStartTransform: MapTransform;
}

function touchPoint(touch: { locationX: number; locationY: number }): ViewportPoint {
  return {
    x: touch.locationX,
    y: touch.locationY,
  };
}

function distance(a: ViewportPoint, b: ViewportPoint): number {
  return Math.hypot(b.x - a.x, b.y - a.y);
}

function angle(a: ViewportPoint, b: ViewportPoint): number {
  return Math.atan2(b.y - a.y, b.x - a.x);
}

function midpoint(a: ViewportPoint, b: ViewportPoint): ViewportPoint {
  return {
    x: (a.x + b.x) / 2,
    y: (a.y + b.y) / 2,
  };
}

function formatTransformValue(value: number): string {
  if (!Number.isFinite(value)) {
    return '0';
  }

  return value.toFixed(2);
}

export function MapViewport({ imageUri, onTransformChange }: MapViewportProps) {
  const [viewport, setViewport] = useState<ViewportDimensions | null>(null);
  const [transform, setTransform] = useState<MapTransform>(createInitialMapTransform);

  const gesture = useRef<GestureTracking>({
    mode: 'none',
    lastPanPoint: null,
    pinchStartDistance: 0,
    pinchStartAngle: 0,
    pinchStartTransform: createInitialMapTransform(),
  });

  useEffect(() => {
    onTransformChange?.(transform);
  }, [onTransformChange, transform]);

  const commitTransform = useCallback((updater: (current: MapTransform) => MapTransform) => {
    setTransform((current) => {
      const next = updater(current);
      return mapTransformsEqual(current, next) ? current : next;
    });
  }, []);

  const panResponder: PanResponderInstance = useMemo(
    () =>
      PanResponder.create({
        onStartShouldSetPanResponder: () => true,
        onMoveShouldSetPanResponder: () => true,
        onPanResponderGrant: (event) => {
          const touches = event.nativeEvent.touches;

          if (touches.length >= 2) {
            const first = touches[0];
            const second = touches[1];
            if (!first || !second) {
              return;
            }

            const a = touchPoint(first);
            const b = touchPoint(second);
            gesture.current.mode = 'pinch';
            gesture.current.pinchStartDistance = distance(a, b);
            gesture.current.pinchStartAngle = angle(a, b);
            gesture.current.pinchStartTransform = transform;
            gesture.current.lastPanPoint = null;
            return;
          }

          const first = touches[0];
          if (!first) {
            return;
          }

          gesture.current.mode = 'pan';
          gesture.current.lastPanPoint = touchPoint(first);
        },
        onPanResponderMove: (event) => {
          const touches = event.nativeEvent.touches;

          if (touches.length >= 2) {
            const first = touches[0];
            const second = touches[1];
            if (!first || !second) {
              return;
            }

            const firstPoint = touchPoint(first);
            const secondPoint = touchPoint(second);

            if (gesture.current.mode !== 'pinch' || gesture.current.pinchStartDistance <= 0) {
              gesture.current.mode = 'pinch';
              gesture.current.pinchStartDistance = distance(firstPoint, secondPoint);
              gesture.current.pinchStartAngle = angle(firstPoint, secondPoint);
              gesture.current.pinchStartTransform = transform;
              gesture.current.lastPanPoint = null;
              return;
            }

            const currentDistance = distance(firstPoint, secondPoint);
            const currentAngle = angle(firstPoint, secondPoint);
            if (!Number.isFinite(currentDistance) || currentDistance <= 0 || !Number.isFinite(currentAngle)) {
              return;
            }

            const scaleFactor = currentDistance / gesture.current.pinchStartDistance;
            const rotationDeltaDeg = ((currentAngle - gesture.current.pinchStartAngle) * 180) / Math.PI;
            const focal = midpoint(firstPoint, secondPoint);

            commitTransform(() =>
              applyPinchRotate(gesture.current.pinchStartTransform, {
                scaleFactor,
                rotationDeltaDeg,
                focal,
                viewport,
              }),
            );

            return;
          }

          if (touches.length === 1) {
            const touch = touches[0];
            if (!touch) {
              return;
            }

            const point = touchPoint(touch);

            if (gesture.current.mode !== 'pan' || !gesture.current.lastPanPoint) {
              gesture.current.mode = 'pan';
              gesture.current.lastPanPoint = point;
              return;
            }

            const delta = {
              x: point.x - gesture.current.lastPanPoint.x,
              y: point.y - gesture.current.lastPanPoint.y,
            };

            commitTransform((current) => applyPanDelta(current, delta));
            gesture.current.lastPanPoint = point;
            return;
          }

          gesture.current.mode = 'none';
          gesture.current.lastPanPoint = null;
        },
        onPanResponderRelease: () => {
          gesture.current.mode = 'none';
          gesture.current.lastPanPoint = null;
          gesture.current.pinchStartDistance = 0;
        },
        onPanResponderTerminate: () => {
          gesture.current.mode = 'none';
          gesture.current.lastPanPoint = null;
          gesture.current.pinchStartDistance = 0;
        },
      }),
    [commitTransform, transform, viewport],
  );

  const onLayout = (event: LayoutChangeEvent) => {
    const { width, height } = event.nativeEvent.layout;
    if (width <= 0 || height <= 0) {
      return;
    }

    setViewport({ width, height });
  };

  const applyScaleAtViewportCenter = (scaleFactor: number) => {
    commitTransform((current) =>
      applyPinchRotate(current, {
        scaleFactor,
        rotationDeltaDeg: 0,
        focal: {
          x: viewport ? viewport.width / 2 : 0,
          y: viewport ? viewport.height / 2 : 0,
        },
        viewport,
      }),
    );
  };

  const applyRotationAtViewportCenter = (rotationDeltaDeg: number) => {
    commitTransform((current) =>
      applyPinchRotate(current, {
        scaleFactor: 1,
        rotationDeltaDeg,
        focal: {
          x: viewport ? viewport.width / 2 : 0,
          y: viewport ? viewport.height / 2 : 0,
        },
        viewport,
      }),
    );
  };

  return (
    <View style={styles.container}>
      <View style={styles.controls}>
        <Pressable onPress={() => applyScaleAtViewportCenter(1.2)} style={styles.controlButton}>
          <Text style={styles.controlButtonText}>Zoom +</Text>
        </Pressable>
        <Pressable onPress={() => applyScaleAtViewportCenter(1 / 1.2)} style={styles.controlButton}>
          <Text style={styles.controlButtonText}>Zoom -</Text>
        </Pressable>
        <Pressable onPress={() => applyRotationAtViewportCenter(-15)} style={styles.controlButton}>
          <Text style={styles.controlButtonText}>Rotate ↺</Text>
        </Pressable>
        <Pressable onPress={() => applyRotationAtViewportCenter(15)} style={styles.controlButton}>
          <Text style={styles.controlButtonText}>Rotate ↻</Text>
        </Pressable>
        <Pressable onPress={() => setTransform(createInitialMapTransform())} style={styles.controlButton}>
          <Text style={styles.controlButtonText}>Reset</Text>
        </Pressable>
      </View>

      <View style={styles.viewport} onLayout={onLayout} {...panResponder.panHandlers}>
        <Image
          source={{ uri: imageUri }}
          resizeMode="contain"
          style={[
